import * as s from "../core/validation/index.js";
import type { Schema } from "../core/validation/schema.js";
import { field11Schema, type Field11 } from "./field11.js";

export type Query = {
  /**
   * | Attribute | Description | Data Type
   * | --- | ----------- | -------
   * | title | Product Title | string |
   * | sku | An arbitrary alphanumeric unique ID, seller-specified, identifying each item | string |
   * | itemId | Specifies the item identifier generated by Walmart | string |
   */
  field?: Field11;
  value?: string;
};

export const querySchema: Schema<Query> = s.object<Query>({
  field: s.optional(s.lazy(() => field11Schema)),
  value: s.optional(s.string()),
});
